create extension if not exists pgcrypto;
alter table public.profiles add column if not exists updated_at timestamptz not null default now();
alter table public.pages add column if not exists updated_at timestamptz not null default now();
alter table public.analytics_events add column if not exists session_id text;
alter table public.analytics_events add column if not exists metadata jsonb not null default '{}'::jsonb;
create table if not exists public.page_sections(id uuid primary key default gen_random_uuid(),page_id uuid not null references public.pages(id) on delete cascade,type text not null,title text,subtitle text,position integer not null default 0,visible boolean not null default true,content jsonb not null default '{}'::jsonb,style jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.social_links(id uuid primary key default gen_random_uuid(),page_id uuid not null references public.pages(id) on delete cascade,platform text not null,title text,url text not null,position integer not null default 0,visible boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,url text not null,position integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.media(id uuid primary key default gen_random_uuid(),page_id uuid not null references public.pages(id) on delete cascade,path text not null,mime_type text,size_bytes bigint,created_at timestamptz not null default now());
create table if not exists public.page_views(id bigint generated always as identity primary key,page_id uuid not null references public.pages(id) on delete cascade,visitor_id text,session_id text,referrer text,user_agent text,device text,browser text,os text,country text,region text,created_at timestamptz not null default now());
create table if not exists public.subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,provider text not null default 'whop',provider_subscription_id text unique,plan text not null default 'free',status text not null default 'active',current_period_end timestamptz,cancel_at_period_end boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.webhook_events(id uuid primary key default gen_random_uuid(),provider text not null,event_id text not null unique,event_type text,payload jsonb not null default '{}',processed_at timestamptz,error text,created_at timestamptz not null default now());
create index if not exists pages_username_idx on public.pages(username);create index if not exists sections_page_position_idx on public.page_sections(page_id,position);create index if not exists products_page_active_idx on public.products(page_id,active);create index if not exists services_page_active_idx on public.services(page_id,active);create index if not exists views_page_created_idx on public.page_views(page_id,created_at desc);create index if not exists events_page_created_idx on public.analytics_events(page_id,created_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
drop trigger if exists pages_updated_at on public.pages;create trigger pages_updated_at before update on public.pages for each row execute function public.set_updated_at();
drop trigger if exists profiles_updated_at on public.profiles;create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at();
alter table public.page_sections enable row level security;alter table public.social_links enable row level security;alter table public.product_images enable row level security;alter table public.media enable row level security;alter table public.page_views enable row level security;alter table public.subscriptions enable row level security;alter table public.webhook_events enable row level security;
create policy sections_public_read on public.page_sections for select using(exists(select 1 from public.pages p where p.id=page_id and p.published=true));create policy sections_owner_all on public.page_sections for all to authenticated using(exists(select 1 from public.pages p where p.id=page_id and p.user_id=(select auth.uid()))) with check(exists(select 1 from public.pages p where p.id=page_id and p.user_id=(select auth.uid())));
create policy social_public_read on public.social_links for select using(exists(select 1 from public.pages p where p.id=page_id and p.published=true));create policy social_owner_all on public.social_links for all to authenticated using(exists(select 1 from public.pages p where p.id=page_id and p.user_id=(select auth.uid()))) with check(exists(select 1 from public.pages p where p.id=page_id and p.user_id=(select auth.uid())));
create policy images_public_read on public.product_images for select using(exists(select 1 from public.products x join public.pages p on p.id=x.page_id where x.id=product_id and p.published=true));create policy images_owner_all on public.product_images for all to authenticated using(exists(select 1 from public.products x join public.pages p on p.id=x.page_id where x.id=product_id and p.user_id=(select auth.uid()))) with check(exists(select 1 from public.products x join public.pages p on p.id=x.page_id where x.id=product_id and p.user_id=(select auth.uid())));
create policy media_owner_all on public.media for all to authenticated using(exists(select 1 from public.pages p where p.id=page_id and p.user_id=(select auth.uid()))) with check(exists(select 1 from public.pages p where p.id=page_id and p.user_id=(select auth.uid())));
create policy views_insert_anon on public.page_views for insert to anon,authenticated with check(exists(select 1 from public.pages p where p.id=page_id and p.published=true));create policy views_owner_read on public.page_views for select to authenticated using(exists(select 1 from public.pages p where p.id=page_id and p.user_id=(select auth.uid())));
create policy subscriptions_owner_read on public.subscriptions for select to authenticated using(user_id=(select auth.uid()));
revoke all on public.webhook_events from anon,authenticated;
